"""Source-art review and proposed character pipeline; no simulated 3D claims."""
from pathlib import Path
from html import escape as e
import json

def render_agents():
    root=Path(__file__).resolve().parents[3]
    packs={name:json.loads((root/f'apps/lab/lib/assets/generated/{name}.json').read_text())['assets'] for name in ['loopforge','loopforge-console','loopforge-supervisors']}
    def pic(pack,key,label):
        vs=packs[pack][key]['variants'];v=vs[0]
        sources=', '.join(f'{x["src"]} {x["width"]}w' for x in vs)
        return f'<figure><a href="{vs[-1]["src"]}" target="_blank" rel="noopener"><img src="{v["src"]}" srcset="{sources}" sizes="(max-width:700px) 90vw, 520px" width="{v["width"]}" height="{v["height"]}" loading="lazy" decoding="async" alt="{e(label)}"></a><figcaption>{e(label)} · original concept reference, not a new 3D render</figcaption></figure>'
    cards=[
      ('Workers','thrum-conveyor','loopforge-supervisors','Worn metal, exposed joints, industrial faces. Smaller and less ornate than a supervisor.','Start with three compatible bodies. Weight transfers into a held brain cradle; hands meet the handles; feet plant at the workstation. Fatigue, hesitation and disorder need readable movement, not only badges.'),
      ('LIMEN','limen-portrait','loopforge-console','Heavy dark armour, a broad silhouette and restrained cyan eyes.','Plant a blocking stance at the gate. Look at a particular worker, stop them, inspect and release or hold. The queue behind them changes.'),
      ('STILETTO','stiletto-portrait','loopforge-console','Narrow black chrome, long segmented limbs, blade forearms and red visor.','Quick decisive turns and impatient checking. Workers hurry in response. Her shortcuts change clearance and exposure; they do not grant engineering ability.'),
      ('Cathexis','cathexis','loopforge','Cracked porcelain, warm eyes, crown/headphones, cable hair and distressed fabric.','Open hands and controlled attention. Workers turn toward her, ignore her or recoil according to their actual response. Influence should spread through bodies.'),
      ('Rivet Witch','witch','loopforge','Hood, green goggles, brass mask, tool belt, cables and heavy boots.','Kneel, brace, inspect, wrench and test at machine contacts. Repair motion only accompanies a real, eligible engineering task.'),
      ('Thrum','thrum','loopforge','Speaker head, blue lens, chest resonator and monk-like cloth.','Deliberate resonant movement. Bodies settle and tension releases; distraction and lost discipline can be visible costs.'),
    ]
    out='<header class="section-head"><span class="kicker">12 October · character direction</span><h2>A factory inhabited by agents.</h2><p>The world is prebuilt. The next visual investment is in its people: recognizable silhouettes, satisfying work and interactions that reveal what the factory is doing to them.</p></header><div class="callout">Agents because they have beliefs, desires and intentions. An LLM is optional. Current runtime figures are placeholders; this is the art and engineering brief for replacing them.</div><p><a href="AGENT_CHARACTER_AND_ANIMATION_DIRECTION.md">Full character and engine plan ↗</a> · <a href="/stepanoskin/loopforge/play">Play the prebuilt opening ↗</a></p><h3>Read the original cast.</h3><p>Open a reference at full size. Preserve body shape, material and gesture before adding fine scratches or more glow.</p><div class="agent-gallery">'
    for name,key,pack,shape,motion in cards:
        out+='<article>'+pic(pack,key,name+' / character and factory reference')+'<div><span class="kicker">'+e(name)+'</span><h3>'+e(shape)+'</h3><p>'+e(motion)+'</p></div></article>'
    out+='</div><h3>One encounter must work from beginning to end.</h3><div class="principle-grid">'
    for label,title,text in [('01 / APPROACH','A worker reaches the gate.','Reserve a real queue slot. Walk to it, slow down, stop and face LIMEN. No feet sliding through a closed gate.'),('02 / CONTACT','LIMEN inspects this worker.','Reserve both actors and the scanner. The credential, hands and device align. A refusal or interruption changes the action.'),('03 / CONSEQUENCE','Release or hold.','The simulation commits the result. Animation and sound express it. The worker moves; the waiting queue and later throughput respond.')]:
        out+=f'<article class="principle"><span class="kicker">{label}</span><h3>{title}</h3><p>{text}</p></article>'
    out+='</div><h3>The same characters; different costs to render.</h3><table class="pairs"><tbody>'
    for label,text in [('Close acting','Authored GLB rigs, clip blends, look targets and limited hand/foot correction for supervisors and close worker interactions.'),('Routine background work','Shared worker meshes/materials. Benchmark baked bone animation for distant repeated tasks; stock Babylon BVA cannot blend actions.'),('The room','Prebuilt geometry enables authored approach/contact points and baked static lighting. A few local dynamic shadows preserve depth.'),('Three feeds','One scene and pose update, three camera passes; one active feed on phones. Count the entire composition, not one camera in isolation.'),('Truth','BDI/action systems own paths, reservations, outcomes and history. The renderer receives permitted action timing and never changes production or trust.')]:out+=f'<tr><th>{label}</th><td>{text}</td></tr>'
    out+='</tbody></table><h3>Next production gate</h3><p>One worker family, LIMEN and STILETTO. Prove a complete gate inspection, a cradle transfer and one supervisor–worker exchange under the real room lighting. Then test 10, 24 and 100 agents before expanding to the rest of the cast.</p><p>Camera changes, quality settings and animation detail must preserve the same agent, task and outcome. Inspect the private causal trace without exposing it to the player prematurely.</p><div class="callout">Delivered now: prebuilt opening, removed builder, versioned command rejection and lazy room rendering. Not yet delivered: new rigs, general BDI, paired character acting or certified crowd performance.</div><p><a href="https://doc.babylonjs.com/features/featuresDeepDive/animation/baked_texture_animations/" target="_blank" rel="noopener">Baked-animation capabilities and limits ↗</a> · <a href="https://doc.babylonjs.com/features/featuresDeepDive/mesh/copies/thinInstances/" target="_blank" rel="noopener">Instance visibility tradeoffs ↗</a></p>'
    return out
